      SUBROUTINE CSAVE      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BSH.CIN'      INCLUDE 'CCENT.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'XYZOLD.CIN'C---------------------------------------------------------------      REAL            POS(3)C      LCOLD = LCPOS      TOTRC = TOTROT      DO 24 J = 1, 3      DO 24 K = 1, 3      OOLD(J,K) = O(4,J,K)   24 CONTINUE      DO 25 J = 1, 3      POS(J) = X0(4,J)   25 CONTINUE      XOLD = POS(1)      YOLD = POS(2)      ZOLD = POS(3)      RETURN      END